{
  "outcome": "patch",
  "candidate_reviews": {
    "C001": {
      "decision": "edit",
      "reason": "Field renamed from SpeedMps to SpeedKph; must scale request.Speed (m/s) by 3.6 before assigning to SpeedKph field."
    },
    "C002": {
      "decision": "edit",
      "reason": "Output key renamed from speed_mps to speed_kph; value must be entity.SpeedKph from parsed entity."
    },
    "C003": {
      "decision": "edit",
      "reason": "Speeding threshold changes from >30.0 to >108.0 (after unit conversion); must use entity.SpeedKph for comparison."
    }
  },
  "edits": [
    {
      "before": "            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, SpeedMps = (float)request.Speed };\n",
      "after": "            var sample = new Simulation.Telemetry.VehicleTelemetry { VehicleId = request.VehicleId, SpeedKph = (float)(request.Speed * 3.6) };\n"
    },
    {
      "before": "            var fields = new Dictionary<string, object> { [\"vehicle_id\"] = entity.VehicleId, [\"speed_mps\"] = entity.SpeedMps };\n",
      "after": "            var fields = new Dictionary<string, object> { [\"vehicle_id\"] = entity.VehicleId, [\"speed_kph\"] = entity.SpeedKph };\n"
    },
    {
      "before": "            return new { fields, speeding = entity.SpeedMps > 30.0, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };\n",
      "after": "            return new { fields, speeding = entity.SpeedKph > 108.0, constructed_payload = Convert.ToBase64String(sample.ToByteArray()) };\n"
    }
  ],
  "rationale": "The schema change renames speed_mps to speed_kph with unit change from m/s to km/h. Producer must scale input by 3.6 before serialization. Consumer observes speed_kph in output JSON. Speeding threshold updates from 30 m/s (108 km/h) to 108 km/h directly using the converted value. All three candidates require modifications to align with the new field name, unit, and threshold.",
  "confidence": 0.95,
  "assumptions": [
    "The regenerated protobuf bindings expose SpeedKph property for field 2",
    "Entity.SpeedKph is populated correctly when parsing base64 payload",
    "JSON output uses double-precision JSON numbers for float32 values",
    "No mixed version/unit scenarios to handle"
  ]
}
